// Category A (overlay) — behavior borrowed from react-aria-components, look owned in src.
// Compound component (shadcn model): compose DrawerTrigger + DrawerContent + DrawerHeader +
// DrawerTitle + DrawerDescription + DrawerFooter. Only the panel sliding from an edge differs;
// composition syntax and structure match Dialog (sibling overlays use the same syntax).
//
// Composition contract — required: DrawerContent (container) + DrawerTitle (accessible name)
// inside a DrawerHeader passed as DrawerContent's `header` prop. The header and footer are PROPS,
// never children, exactly as on Dialog: they render as siblings of the scrolling body, so nothing
// scrolls under them and the panel's one surface shows through. A DrawerHeader or DrawerFooter
// passed as a child renders as plain body content, without its placement: do not do it.
// Optional: DrawerDescription · body slot (children) · footer (DrawerFooter) · close button
// (DrawerContent showCloseButton).
// Enforce through types/composition only (no runtime guard — codebase convention).
import {
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Heading,
  Modal,
  ModalOverlay,
} from "react-aria-components";
import type {
  DialogTriggerProps as AriaDialogTriggerProps,
  ModalOverlayProps,
} from "react-aria-components";
import { X } from "./icons";
import { ButtonGroup } from "./ButtonGroup";
import { Button } from "./Button";
import { FeaturedIcon } from "./FeaturedIcon";
import { Children, useCallback, useRef, useState } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./Drawer.css";

/** Make the scrollport focusable only when it actually overflows. An unconditional tabIndex=0
    creates an “unnamed empty tab stop” even in a dialog without scrolling, and draws an inset
    focus ring around the whole panel that looks like a rendering bug (axe does not catch it,
    and it is not visible in screenshots that capture only the default state). */
function useIsScrollable() {
  const [isScrollable, setIsScrollable] = useState(false);
  const observer = useRef<ResizeObserver | null>(null);
  // This must be a callback ref: the panel mounts when the overlay “opens,” but this component does
  // not rerender then, so useEffect + a ref object cannot catch the moment the node attaches (it
  // always runs once with null and finishes).
  const ref = useCallback((el: HTMLDivElement | null) => {
    observer.current?.disconnect();
    observer.current = null;
    if (!el) {
      setIsScrollable(false);
      return;
    }
    const update = () => setIsScrollable(el.scrollHeight > el.clientHeight);
    const ro = new ResizeObserver(update);
    ro.observe(el);
    for (const child of Array.from(el.children)) ro.observe(child);
    observer.current = ro;
    update();
  }, []);
  return [ref, isScrollable] as const;
}

export interface DrawerTriggerProps extends AriaDialogTriggerProps {}

export function DrawerTrigger(props: DrawerTriggerProps) {
  return <AriaDialogTrigger {...props} />;
}

// There is deliberately NO `surface` prop. The overlay layer's treatment — opaque or frosted — is
// the THEME'S (`<html data-surface="translucent">`), and this component reads it and nothing else.
// A prop would let an app frost its dialogs and popovers and still ship a solid drawer, with no call
// site to blame, and the legibility exception such a prop would serve is already discharged by the
// contract: the translucent surface's opacity is
// DERIVED as the least opaque step at which text · text-muted · text-brand all still clear 4.5:1
// composited over pure black AND pure white, so a frosted panel is legible over any backdrop by
// construction. All the exception could still buy was the incoherence ADR-0022 removed.
export interface DrawerContentProps
  extends Omit<ModalOverlayProps, "className" | "children" | "style"> {
  /**
   * How the panel attaches to the viewport. `inset` (default) is a floating card with spacing on
   * every side (all four corners rounded) · `full-bleed` touches the edge (only corners opposite
   * the docked edge are rounded) — the conventional drawer form. Uses the same vocabulary as
   * DialogCover.
   *
   * @default "inset"
   */
  variant?: "inset" | "full-bleed";
  /**
   * Edge from which the panel slides. `end` (default) · `start` · `top` · `bottom`. `sheet` is a
   * bottom sheet below the `large` breakpoint and a centred panel at and above it: ONE overlay that
   * changes shape by width, so crossing the breakpoint while open keeps its focus and its fields.
   *
   * @default "end"
   */
  side?: "start" | "end" | "top" | "bottom" | "sheet";
  /** Whether to show the top-right close (X) button. Defaults to true when a `header` is given
      and false without one, since the close sits in the header's row. It is absolutely positioned
      at the panel frame's top-right and pinned independently of scrolling. Set false to hide it
      for forced-choice drawers. */
  showCloseButton?: boolean;
  /** Accessible name of the close (X) button, for a screen that is not in English.
      @default "Close" */
  closeLabel?: string;
  /** The header — a DrawerHeader holding the DrawerTitle (the accessible name). Rendered above the
      scrolling body, so it stays in view while a long body scrolls. */
  header?: ReactNode;
  /** The body slot: what scrolls. Headers and footers go in `header` / `footer`, never here. */
  children?: ReactNode;
  /** The footer — a DrawerFooter with the actions. Rendered below the scrolling body, so on a
      full-height drawer it sits at the panel bottom whatever the body holds. */
  footer?: ReactNode;
  /** Optional accessible name — normally unnecessary because DrawerTitle provides the name. Use
      only in the rare case with no Title. Forwarded to the role="dialog" element. */
  "aria-label"?: string;
  /** Optional id referencing the accessible name — forwarded to the role="dialog" element. */
  "aria-labelledby"?: string;
  /** Optional id referencing the accessible description — forwarded to the role="dialog" element.
      React Aria links only the title automatically (slot="title" → aria-labelledby), so to have a
      screen reader read the description on open, give DrawerDescription an id and pass it here. */
  "aria-describedby"?: string;
  /** Additional class (optional). sd-drawer__content is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the content panel (sd-drawer__content) DOM node (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying content panel (sd-drawer__content) DOM node (the same element as className · style). */
  ref?: Ref<HTMLDivElement>;
}

export function DrawerContent({
  variant = "inset",
  side = "end",
  header,
  // No header, no close by default: the close sits in the header's row, and without one it
  // lands on whatever region comes first (measured on FooterOnly: over the primary action).
  showCloseButton = Boolean(header),
  closeLabel = "Close",
  children,
  footer,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-describedby": ariaDescribedBy,
  className,
  style,
  isDismissable = true,
  ref,
  ...props
}: DrawerContentProps) {
  const [scrollRef, isScrollable] = useIsScrollable();
  const hasBody = Children.toArray(children).length > 0;
  return (
    <ModalOverlay
      {...props}
      isDismissable={isDismissable}
      data-variant={variant}
      data-side={side}
      className="sd-drawer__overlay"
    >
      <Modal
        ref={ref}
        data-variant={variant}
        data-side={side}
        // No `data-surface` here, at all: the only `[data-surface]` in the system is the one on
        // <html>, which swaps the Sys tokens this panel's background relay reads. Emitting one on
        // the panel would shadow the theme for that instance — the escape hatch this component no
        // longer offers (see the note above the props).
        style={style}
        className={className ? `sd-drawer__content ${className}` : "sd-drawer__content"}
      >
        {/* data-has-close drives the header's close-clearance intermediate (contract §6 rule 5):
            the state lives on the panel, the padding is applied on the header child. */}
        <AriaDialog
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          aria-describedby={ariaDescribedBy}
          data-has-close={showCloseButton || undefined}
          // Which regions are present decides each seam (Drawer.css § the three regions).
          data-has-header={header ? true : undefined}
          data-has-body={hasBody || undefined}
          data-has-footer={footer ? true : undefined}
          className="sd-drawer__panel"
        >
          {showCloseButton && (
            <div className="sd-drawer__close">
              <Button slot="close" variant="ghost" isIconOnly size="medium" aria-label={closeLabel}>
                <X aria-hidden size="1em" />
              </Button>
            </div>
          )}
          {header}
          {/* Because the scrollport is a descendant of the role="dialog" element (panel), the
              initial focus React Aria gives the panel does not enable keyboard scrolling
              (PageDown/arrows) — browsers scroll a focused element's scrollable *ancestor*.
              Therefore the scrolling area itself is focusable (the same convention as ScrollArea,
              WCAG 2.1.1), and only while it actually overflows: `data-scrollable` states the same
              fact as `tabIndex` on the same element, so the two cannot diverge. Not rendered at
              all without body content, so a header and footer alone meet at one seam. */}
          {hasBody && (
            <div
              ref={scrollRef}
              className="sd-drawer__scroll"
              data-scrollable={isScrollable || undefined}
              tabIndex={isScrollable ? 0 : undefined}
            >
              <div className="sd-drawer__body">{children}</div>
            </div>
          )}
          {footer}
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
}

export interface DrawerHeaderBaseProps {
  /**
   * Alignment axis. `center` centers the leading visual · title · description (alert/confirmation
   * forms). Defaults to `start`.
   *
   * @default "start"
   */
  align?: "start" | "center";
}

/**
 * DrawerHeader props.
 *
 * There can be only one leading visual, an icon **or** an image — because the header is a vertical
 * column, passing both silently breaks it by stacking them. Therefore exclusivity is enforced at
 * the **type level**, not merely in documentation (contract §2 discriminated-union carve-out — the
 * same as Dialog · Button).
 */
export type DrawerHeaderProps = DrawerHeaderBaseProps &
  (
    | {
        /** Optional leading icon — a glyph contained in the shared `FeaturedIcon` plate (neutral
            rounded box). Pass `size="1em"` and the plate determines its size from its own tokens. */
        icon?: ReactNode;
        image?: never;
      }
    | {
        /** Optional leading image — a photo/thumbnail (avatar · logo) that fills the same
            `FeaturedIcon` plate. Give the media the `sd-featured-icon__media` class to crop it to
            the plate (object-fit: cover). */
        image?: ReactNode;
        icon?: never;
      }
  ) & {
    /** Header content (optional wrapper) — normally the required DrawerTitle (+ optional DrawerDescription). */
    children?: ReactNode;
    /** Additional class (optional). sd-drawer__header is always preserved. */
    className?: string;
    /** Optional inline style — forwarded to the header <div> (the same element as className). */
    style?: CSSProperties;
    /** Forwarded to the underlying <div> DOM node. */
    ref?: Ref<HTMLDivElement>;
  };

export function DrawerHeader({
  align = "start",
  icon,
  image,
  children,
  className,
  style,
  ref,
}: DrawerHeaderProps) {
  return (
    <div
      ref={ref}
      data-align={align}
      style={style}
      className={className ? `sd-drawer__header ${className}` : "sd-drawer__header"}
    >
      {/* Both leading visuals are the shared FeaturedIcon plate — it owns the geometry (size,
          radius, glyph size, clipping) and sets no colour, so the glyph keeps inheriting the
          panel foreground. `sunken` because the plate sits on the panel's plain white surface,
          where Alert's sits on a status tint (`raised`). */}
      {icon && (
        <FeaturedIcon aria-hidden="true" size="large" tone="sunken" className="sd-drawer__icon">
          {icon}
        </FeaturedIcon>
      )}
      {image && (
        <FeaturedIcon aria-hidden="true" size="large" tone="sunken" className="sd-drawer__image">
          {image}
        </FeaturedIcon>
      )}
      <div className="sd-drawer__header-text">{children}</div>
    </div>
  );
}

export interface DrawerTitleProps {
  /** Title content. **Required** — becomes the drawer's accessible name (slot="title" → aria-labelledby). */
  children?: ReactNode;
  /** Additional class (optional). sd-drawer__title is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the title heading (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying heading DOM node (the same element as className · style). */
  ref?: Ref<HTMLHeadingElement>;
}

export function DrawerTitle({ className, style, ref, ...props }: DrawerTitleProps) {
  return (
    <Heading
      {...props}
      ref={ref}
      style={style}
      slot="title"
      className={
        className
          ? `sd-drawer__title sd-type-title-medium ${className}`
          : "sd-drawer__title sd-type-title-medium"
      }
    />
  );
}

export interface DrawerDescriptionProps {
  /** Optional description content — supporting text below the title. */
  children?: ReactNode;
  /** Optional element id — pass it to DrawerContent's `aria-describedby` to link the accessible description. */
  id?: string;
  /** Additional class (optional). sd-drawer__description is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the description <p> (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying <p> DOM node (the same element as className · style). */
  ref?: Ref<HTMLParagraphElement>;
}

export function DrawerDescription({ className, style, ref, ...props }: DrawerDescriptionProps) {
  return (
    <p
      {...props}
      ref={ref}
      style={style}
      className={
        className
          ? `sd-drawer__description sd-type-body-medium ${className}`
          : "sd-drawer__description sd-type-body-medium"
      }
    />
  );
}

export interface DrawerFooterProps {
  /**
   * Action layout — `end` (default) right-aligns · buttons hug; `center` splits evenly left/right
   * (equal-width filled buttons) · centers description; `stack` makes a vertical full-width stack ·
   * centers description under it; `fill` keeps one row at every size, the aside action hugging and the
   * primary filling the rest. (layout owns only action-button placement.) The same axis as DialogFooter
   * — sibling overlays use the same footer model.
   *
   * @default "end"
   */
  layout?: "end" | "center" | "stack" | "fill";
  /** Optional help/fine print, spanning the full width. Above the actions in a row layout (`end`,
      `center`, `fill`), where it is the fine print the actions act on; directly UNDER the action in
      `stack`, where it is the reassurance line that answers the action ("상담 신청만으로 계약되지
      않아요"), read after it. It can be used with every layout. */
  description?: ReactNode;
  /** Optional footer content — action buttons, etc. */
  children?: ReactNode;
  /** Additional class (optional). sd-drawer__footer is always preserved. */
  className?: string;
  /** Optional inline style — forwarded to the footer <div> (the same element as className). */
  style?: CSSProperties;
  /** Forwarded to the underlying <div> DOM node (the same element as className · style). */
  ref?: Ref<HTMLDivElement>;
}

export function DrawerFooter({
  layout = "end",
  description,
  children,
  className,
  style,
  ref,
}: DrawerFooterProps) {
  // One rung below the header `description` it closes — CONTRASTIVE, and both are on screen at once
  // (`naming-convention.md` § The size axis defaults to `medium`).
  const note = description && (
    <p data-layout={layout} className="sd-drawer__footer-description sd-type-body-small">
      {description}
    </p>
  );
  // A stack's line follows its action in the DOM as on screen, so it is read after it too.
  const isUnder = layout === "stack";
  return (
    <div
      ref={ref}
      style={style}
      className={className ? `sd-drawer__footer ${className}` : "sd-drawer__footer"}
    >
      {!isUnder && note}
      <ButtonGroup layout={layout}>{children}</ButtonGroup>
      {isUnder && note}
    </div>
  );
}

/* Drawer.css — .sd-drawer__* (포털 오버레이)
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태는 react-aria data-* / Cmp 토큰 참조.
   구조는 형제 오버레이인 Dialog 와 동일하다: overlay(스크림) > content(프레임) > panel(role=dialog
   레이아웃 컬럼) > header · scroll(스크롤포트) > body(패딩 컬럼) · footer. header/footer 는 스크롤포트의
   형제라 그 아래로 스크롤되는 내용이 없다. */
.sd-drawer__overlay {
  position: fixed;
  inset: 0;
  z-index: var(--sd-drawer-overlay-z-index);
  display: flex;
  background: var(--sd-drawer-overlay-background);
}
/* `inset` (default) — the panel floats clear of the viewport edge, so all four of its corners are
   visible and rounded. `full-bleed` docks it flush to the edge (the conventional drawer) and only
   the corners facing *into* the viewport round. Same vocabulary as DialogCover. */
.sd-drawer__overlay[data-variant="inset"] {
  padding: var(--sd-drawer-overlay-padding);
}
/* Keep-out: the panel must never cover the whole viewport, so the edge OPPOSITE the docking side
   always keeps `content-margin` of scrim — enough that a drawer reads as sliding over a screen
   rather than replacing it. Declared after the variant rule (equal specificity) so it overrides
   that one side for `inset`, and supplies the only padding for `full-bleed`. Logical properties,
   so `start`/`end` stay correct under `dir="rtl"`. */
.sd-drawer__overlay[data-side="start"] {
  padding-inline-end: var(--sd-drawer-content-margin);
}
.sd-drawer__overlay[data-side="end"] {
  padding-inline-start: var(--sd-drawer-content-margin);
}
.sd-drawer__overlay[data-side="top"] {
  padding-block-end: var(--sd-drawer-content-margin);
}
.sd-drawer__overlay[data-side="bottom"],
.sd-drawer__overlay[data-side="sheet"] {
  padding-block-start: var(--sd-drawer-content-margin);
}

.sd-drawer__overlay[data-side="start"] {
  justify-content: flex-start;
  align-items: stretch;
}

.sd-drawer__overlay[data-side="end"] {
  justify-content: flex-end;
  align-items: stretch;
}

.sd-drawer__overlay[data-side="top"] {
  align-items: flex-start;
}

.sd-drawer__overlay[data-side="bottom"],
.sd-drawer__overlay[data-side="sheet"] {
  align-items: flex-end;
}

.sd-drawer__overlay[data-entering] {
  animation: sd-drawer-overlay-enter var(--sd-drawer-animation-duration) var(--sd-easing-decelerate);
}

.sd-drawer__overlay[data-exiting] {
  animation: sd-drawer-overlay-exit var(--sd-drawer-animation-duration) var(--sd-easing-accelerate);
}

/* content — the outer panel frame (size/radius/border/shadow + the slide animation target).
   A flex column holding the single `panel`; overflow:hidden clips the radius, and the scrollport
   inside owns the scroll so the close button can stay pinned. */
.sd-drawer__content {
  display: flex;
  flex-direction: column;
  /* Surface treatment — the panel's paper and its blur, read straight from the THEME and from
     nothing else. `--sd-drawer-content-background` / `-backdrop-filter` are this component's relays
     for the Sys `surface-treatment.overlay-*` pair, which `[data-surface]` on <html> swaps
     (tokens.css). Under a standard theme they resolve to the opaque overlay surface and `none`, `backdrop-filter`'s initial value, which creates no
     backdrop root or containing block.

     This is a THEME decision rather than a per-call-site one so that no overlay, a drawer included,
     is silently off-system in a "frosted" app (ADR-0022). Glass is the third element
     of elevation, alongside surface lightness and shadow. No instance may depart from it; see the
     note below this rule. -webkit- prefix for Safari, which shipped the prefixed form long before
     the unprefixed one, and it is declared on every element that paints the treatment, since a
     var() carries a value, not a property name.

     The header and footer are siblings of the scrolling body (DrawerContent's `header` / `footer`
     props), so they paint no surface of their own and the panel's one surface shows through all
     three regions; Dialog.css § content says why a band inside the scrollport cannot. */
  background: var(--sd-drawer-content-background);
  -webkit-backdrop-filter: var(--sd-drawer-content-backdrop-filter);
  backdrop-filter: var(--sd-drawer-content-backdrop-filter);
  color: var(--sd-drawer-content-foreground);
  border: var(--sd-drawer-content-border-width) solid var(--sd-drawer-content-border);
  border-radius: var(--sd-drawer-content-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: var(--sd-drawer-content-shadow);
  overflow: hidden;
}
/* No `[data-surface]` rule on this panel — deliberately. The only `[data-surface]` in the system is
   the one on <html> (tokens.css), which swaps the Sys pair the base rule above already reads. A
   per-instance departure has no case to serve, because the CONTRACT closes it: `standard` ("this
   panel's legibility must win over the backdrop") is unnecessary, since the translucent surface's opacity is
   DERIVED as the least opaque step at which text, text-muted and text-brand all still clear 4.5:1
   composited over pure black AND pure white (plan-color.mjs § the translucent overlay surface). A
   frosted panel is legible over any backdrop by construction, and stays legible where
   `backdrop-filter` is unsupported — the filter is the enhancement, the surface carries the contract.
   The other value, `translucent` under a solid theme, is the mixed-overlay incoherence ADR-0022
   removes. A consumer who needs one panel to disagree owns this
   copied file. */

/* full-bleed: the docking edge meets the viewport, so only the two corners on the opposite edge
   round. Logical longhands (not a physical shorthand) so a `start`/`end` drawer stays correct
   under `dir="rtl"`, where those sides swap. */
.sd-drawer__content[data-variant="full-bleed"] {
  border-radius: 0;
}
.sd-drawer__content[data-variant="full-bleed"][data-side="start"] {
  border-start-end-radius: var(--sd-drawer-content-radius);
  corner-start-end-shape: superellipse(var(--sd-radius-curve));
  border-end-end-radius: var(--sd-drawer-content-radius);
  corner-end-end-shape: superellipse(var(--sd-radius-curve));
}
.sd-drawer__content[data-variant="full-bleed"][data-side="end"] {
  border-start-start-radius: var(--sd-drawer-content-radius);
  corner-start-start-shape: superellipse(var(--sd-radius-curve));
  border-end-start-radius: var(--sd-drawer-content-radius);
  corner-end-start-shape: superellipse(var(--sd-radius-curve));
}
.sd-drawer__content[data-variant="full-bleed"][data-side="top"] {
  border-end-start-radius: var(--sd-drawer-content-radius);
  corner-end-start-shape: superellipse(var(--sd-radius-curve));
  border-end-end-radius: var(--sd-drawer-content-radius);
  corner-end-end-shape: superellipse(var(--sd-radius-curve));
}
.sd-drawer__content[data-variant="full-bleed"][data-side="bottom"],
.sd-drawer__content[data-variant="full-bleed"][data-side="sheet"] {
  border-start-start-radius: var(--sd-drawer-content-radius);
  corner-start-start-shape: superellipse(var(--sd-radius-curve));
  border-start-end-radius: var(--sd-drawer-content-radius);
  corner-start-end-shape: superellipse(var(--sd-radius-curve));
}

/* panel — the role="dialog" element + the layout column. It is the positioning context for the
   pinned close and holds it *inside* the dialog (so `slot="close"` wiring + a11y are correct). */
.sd-drawer__panel {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  outline: none;
  /* 8 on BOTH sides. Reserving the close button's own width here (`--sd-<c>-close-size`, 40) would
     make the header read as a 40px inset against the panel's other content. The close floats above
     the title, and the title's own clearance keeps a long one from passing beneath it. */
}
/* scroll — the scrollport (the only scroller), between the header and the footer, and the region
   that gives way: `flex: 1` so a full-height drawer's footer sits at the panel bottom whatever the
   body holds. The padded body inside owns the content insets; the scrollport's only padding is
   the focus-ring room below. */
.sd-drawer__scroll {
  /* §6-3: the DS ring is drawn below, so the UA outline is reset on the BASE rule —
     inside the focus rule it lands too late and the OS accent paints alongside ours. */
  outline: none;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  /* Under a header the body's block-start padding is 0, so a field that opens the body sat flush
     against this clip and lost the top of its focus ring (DrawerForm's first field). Ring room
     with the margin given straight back, as `.sd-tabs__scroll` does, so no seam moves (contract
     §6 rule 7). */
  padding-block: var(--sd-state-focus-ring-width);
  margin-block: calc(-1 * var(--sd-state-focus-ring-width));
}
/* The three regions — header, body, footer — are siblings, and which of them are present decides
   each seam, exactly as on Dialog (Dialog.css § the three regions carries the reasoning): every
   combination lands on the spacing the header and footer had inside the body. */
.sd-drawer__panel:not([data-has-body]):not([data-has-footer]) {
  --sd-drawer-header-padding-block-end-current: var(--sd-drawer-body-padding-block);
}
.sd-drawer__panel:not([data-has-header]) {
  --sd-drawer-body-padding-block-start-current: var(--sd-drawer-body-padding-block);
}
.sd-drawer__panel:not([data-has-footer]) {
  --sd-drawer-body-padding-block-end-current: var(--sd-drawer-body-padding-block);
}
.sd-drawer__panel:not([data-has-header]):not([data-has-body]) {
  --sd-drawer-footer-padding-block-start-current: calc(var(--sd-drawer-body-padding-block) + var(--sd-drawer-footer-padding-block-start));
}
/* The scrollport is focusable (keyboard scrolling, WCAG 2.1.1), so it needs a visible focus
   indicator meeting the 3:1 contract — the UA default ring is both off-palette and too low in
   dark. Inset, because the frame's overflow:hidden would clip an outward ring. */
.sd-drawer__scroll:focus-visible {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* A side drawer on the small rung fills what the overlay leaves, so every edge it does not dock to
   keeps the page margin and nothing else: capped at its width token, a 320px panel on a 390px
   screen would leave a 50px strip that is no margin at all. From `medium` up the
   width token caps it and the strip it leaves is the drawer's width at work. */
.sd-drawer__content[data-side="start"],
.sd-drawer__content[data-side="end"] {
  width: 100%;
  height: 100%;
}
@media (min-width: 768px) {
  .sd-drawer__content[data-side="start"],
  .sd-drawer__content[data-side="end"] {
    width: min(var(--sd-drawer-content-size), 100%);
  }
}

/* A top/bottom drawer and the sheet are sized by their CONTENT up to a cap. The overlay's padding
   does not hold them: they are cross-axis flex items, so a tall body grew the panel past the
   viewport (a 936px form in an 844px phone viewport put the header 92px above the top, close and
   all). The cap is the smaller of the overlay's padded box (`100%`, which carries the keep-out and,
   for `inset`, the docking-edge padding exactly) and the visual-viewport cap token (an on-screen
   keyboard shrinks the visual viewport, not the fixed overlay). The header and footer then stay on
   screen and only `__scroll` gives way. */
.sd-drawer__content[data-side="top"],
.sd-drawer__content[data-side="bottom"],
.sd-drawer__content[data-side="sheet"] {
  width: 100%;
  max-height: min(100%, var(--sd-drawer-content-max-height));
}

.sd-drawer__content[data-side="start"][data-entering] {
  animation: sd-drawer-content-start-enter var(--sd-drawer-animation-duration) var(--sd-easing-decelerate);
}

.sd-drawer__content[data-side="start"][data-exiting] {
  animation: sd-drawer-content-start-exit var(--sd-drawer-animation-duration) var(--sd-easing-accelerate);
}

.sd-drawer__content[data-side="end"][data-entering] {
  animation: sd-drawer-content-end-enter var(--sd-drawer-animation-duration) var(--sd-easing-decelerate);
}

.sd-drawer__content[data-side="end"][data-exiting] {
  animation: sd-drawer-content-end-exit var(--sd-drawer-animation-duration) var(--sd-easing-accelerate);
}

/* Inline start/end swap under RTL. Keep the horizontal motion on `transform` so these panel
   animations remain compositor-friendly, but select sign-flipped keyframes on the same element. */
.sd-drawer__content[data-side="start"][data-entering]:dir(rtl) {
  animation-name: sd-drawer-content-start-enter-rtl;
}

.sd-drawer__content[data-side="start"][data-exiting]:dir(rtl) {
  animation-name: sd-drawer-content-start-exit-rtl;
}

.sd-drawer__content[data-side="end"][data-entering]:dir(rtl) {
  animation-name: sd-drawer-content-end-enter-rtl;
}

.sd-drawer__content[data-side="end"][data-exiting]:dir(rtl) {
  animation-name: sd-drawer-content-end-exit-rtl;
}

.sd-drawer__content[data-side="top"][data-entering] {
  animation: sd-drawer-content-top-enter var(--sd-drawer-animation-duration) var(--sd-easing-decelerate);
}

.sd-drawer__content[data-side="top"][data-exiting] {
  animation: sd-drawer-content-top-exit var(--sd-drawer-animation-duration) var(--sd-easing-accelerate);
}

.sd-drawer__content[data-side="bottom"][data-entering],
.sd-drawer__content[data-side="sheet"][data-entering] {
  animation: sd-drawer-content-bottom-enter var(--sd-drawer-animation-duration) var(--sd-easing-decelerate);
}

.sd-drawer__content[data-side="bottom"][data-exiting],
.sd-drawer__content[data-side="sheet"][data-exiting] {
  animation: sd-drawer-content-bottom-exit var(--sd-drawer-animation-duration) var(--sd-easing-accelerate);
}

/* body — the padded content column inside the scrollport. Its block padding gives way to the
   header and footer seams (the relays above); inline padding stays here so slotted media can go
   full-bleed. */
.sd-drawer__body {
  display: flex;
  flex-direction: column;
  gap: var(--sd-drawer-body-gap);
  padding-block-start: var(--sd-drawer-body-padding-block-start-current, 0);
  padding-block-end: var(--sd-drawer-body-padding-block-end-current, var(--sd-drawer-body-gap));
  padding-inline: var(--sd-drawer-body-padding-inline);
  /* A flat GridList's rows are boxes that pad their own text, so in this body their text stood a
     row's padding past the title. This switch moves them out into the body's padding until their
     text meets the title's start (GridList.css § outset). ListBox and Tree rows need none: their
     text already stands one inset in and their fill bleeds on its own. */
  --sd-grid-list-item-outset-current: 1;
}


/* header — above the scrolling body, a sibling of it, so it stays in view while a long body slot
   scrolls and paints nothing of its own; `flex-shrink: 0`, since the scrollport is what gives way.
   The band takes the body's inset on its sides and top, and `__header-text` adds the text inset
   inside it, since the panel draws that text on its own surface (component-contract.md §6 rule 8);
   block-end is the seam to what follows (the relays above). The end
   side reserves nothing for the close (it is ABSOLUTE on the panel), since that would read as a
   40px inset; the clearance sits on the title instead. */
.sd-drawer__header {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--sd-drawer-header-gap);
  /* The header is one band of the panel: the panel's own surface padding on its sides and top, the
     same token the body and footer spend. The text group inside adds the text inset, and a leading
     plate takes the band's edge as a box does (component-contract.md §6 rule 8). */
  padding-block-start: var(--sd-drawer-body-padding-block);
  padding-block-end: var(--sd-drawer-header-padding-block-end-current, var(--sd-drawer-body-gap));
  padding-inline: var(--sd-drawer-body-padding-inline);
}
/* center alignment (alert/confirm drawers) — leading·title·description centered. The close
   clearance is mirrored onto the start side so the centered content stays optically centered. */
.sd-drawer__header[data-align="center"] {
  align-items: center;
  text-align: center;
}
/* title + description group. */
.sd-drawer__header-text {
  display: flex;
  flex-direction: column;
  gap: var(--sd-drawer-header-text-gap);
  align-self: stretch;
  /* Text the panel always draws on its own surface takes the text inset (component-contract.md §6
     rule 8, component-owned text); a leading plate stays on the band's edge, as a box does. Inline
     only: `text-inset.block` is spent by no part. */
  padding-inline: var(--sd-drawer-header-padding-inline-start);
}
/* The two mutually-exclusive leading visuals (`icon` / `image`) carry no rules of their own: both
   render the shared FeaturedIcon plate, which owns the square, the radius, the neutral fill, the
   glyph size and the media clipping — including the `flex: 0 0 auto` that keeps the plate from
   shrinking in this header row. Only the BEM part class stays, as the Figma layer name. */

/* Panel text wraps rather than overflowing: the panel is a fixed-width scrollport, so a long
   unbreakable string would otherwise force horizontal scroll. */
/* Close clearance on the title alone — see the matching rule in Dialog.css for the full reasoning.
   Measured overlap before this: 26.2px at the small rung, 4.4px at medium/large. */
.sd-drawer__title {
  margin: 0;
  color: var(--sd-drawer-title-foreground);
  overflow-wrap: anywhere;
  padding-inline-end: var(--sd-drawer-title-close-clearance-current, 0);
  /* Mirrored on centered headers — see Dialog.css for the reasoning. */
  padding-inline-start: var(--sd-drawer-title-close-clearance-start-current, 0);
}
.sd-drawer__header[data-align="center"] {
  --sd-drawer-title-close-clearance-start-current: var(--sd-drawer-title-close-clearance-current, 0);
}
.sd-drawer__panel[data-has-close] {
  --sd-drawer-title-close-clearance-current: calc(
    var(--sd-drawer-close-inset) + var(--sd-drawer-close-size) -
    var(--sd-drawer-body-padding-inline) - var(--sd-drawer-header-padding-inline-start)
  );
}
.sd-drawer__description {
  margin: 0;
  /* The header-text column already stands its text one inset in (its title measures the close
     clearance from that edge), so the description's role adds none of its own. */
  padding-inline: 0;
  color: var(--sd-drawer-description-foreground);
  overflow-wrap: anywhere;
}

/* Close = the shared Button (variant="ghost", isIconOnly) in a positioned wrapper — all look/state
   comes from Button; the wrapper only positions it. Pinned to the panel's top-inline-end corner
   (absolute; `.sd-drawer__panel` is the positioning context) so it stays put while the body
   scrolls. z-index keeps it above anything a consumer positions in the header. */
.sd-drawer__close {
  position: absolute;
  top: var(--sd-drawer-close-inset);
  inset-inline-end: var(--sd-drawer-close-inset);
  z-index: 2;
  display: inline-flex;
}

/* footer — below the scrolling body, a sibling of it: an optional helper `description` (full-width,
   above the actions row, or under the action in `stack`) + the actions row. Same two-part shape as DialogFooter — the sibling overlays share one
   footer model. The actions row owns the layout (end/center/stack); the description is orthogonal.
   Inline it sits at the body's inset; block-start is its own inset after a header or body and the
   body's block inset plus its own when it is the panel's first region; block-end is the body's
   inset, so the actions clear the panel's rounded corner. */
.sd-drawer__footer {
  flex-shrink: 0;
  /* At the panel bottom even with no body: a full-height drawer holding only a header and a footer
     has no scrollport to fill the space, and this margin takes it. Inert when the scrollport is
     present (it fills the space first) and on a top/bottom sheet, which is sized by its content. */
  margin-block-start: auto;
  display: flex;
  flex-direction: column;
  gap: var(--sd-drawer-footer-gap);
  padding-block-start: var(--sd-drawer-footer-padding-block-start-current, var(--sd-drawer-footer-padding-block-start));
  padding-block-end: var(--sd-drawer-body-padding-block);
  padding-inline: var(--sd-drawer-body-padding-inline);
}
/* helper / fine-print line above the actions, or under them in `stack` (muted; reuses the
   description color). It aligns with
   the actions: left for end (default), centered for the symmetric center/stack layouts. The layout
   is set on the description element itself (same-element selector, no child combinator). */
.sd-drawer__footer-description {
  margin: 0;
  color: var(--sd-drawer-description-foreground);
  overflow-wrap: anywhere;
  /* The same inset the header title takes: text the panel draws on its own surface. */
  padding-inline: var(--sd-drawer-footer-description-padding-inline);
}
.sd-drawer__footer-description[data-layout="center"],
.sd-drawer__footer-description[data-layout="stack"] {
  text-align: center;
}
/* actions row layout cases: end (default) right-aligned · center equal side-by-side (grid, no
   child selectors) · stack full-width vertical. The button↔button gap is its own token, a rung
   tighter than the footer's description↔actions gap on the column, so the buttons read as one
   group inside the footer rather than as siblings of the description. */



